var longestConsecutive = function(nums) {
    const numSet = new Set(nums);
    let longest = 0;
    for (const num of numSet) {
        if (!numSet.has(num - 1)) {
            let curr = num;
            let streak = 1;
            while (numSet.has(curr + 1)) {
                curr++;
                streak++;
            }
            if (streak > longest) {
                longest = streak;
            }
        }
    }
    return longest;
};
